launcher_source:
$ErrorActionPreference='Stop'
$script='D:\upmix\tools\run_spectral_context_generalization.ps1'
if((Get-FileHash $script -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'debc2a8e43203c6d27e35b478c3a5a0a8fb51bb8f3da8835699458a7ab8ae8f4'){throw 'Prepared broad runner changed'}
$wrapper=Join-Path $env:TEMP 'upmix_spectral_broad_wrapper_v1.ps1'
$log=Join-Path $env:TEMP 'upmix_spectral_broad_live_v1.log'
if((Test-Path $wrapper) -or (Test-Path $log)){throw 'Preserve prior broad launch'}
$content=@"
`$ErrorActionPreference='Stop'
try { & '$script' *> '$log'; exit 0 } catch { `$_ | Out-File -Append '$log'; exit 1 }
"@
[IO.File]::WriteAllText($wrapper,$content,[Text.Encoding]::UTF8)
$r=Invoke-CimMethod -ClassName Win32_Process -MethodName Create -Arguments @{CommandLine="powershell.exe -NoProfile -ExecutionPolicy Bypass -File $wrapper"}
@{return_value=$r.ReturnValue;supervisor_pid=$r.ProcessId;log=$log}|ConvertTo-Json -Compress
if($r.ReturnValue -ne 0){throw 'Detached broad launch failed'}
